int kmpSearch(const char *s, const char *p) {
    int n = 0, m = 0;
    while (s[n] != '\0') n++;
    while (p[m] != '\0') m++;
    if (m == 0) return 0;
    if (n < m) return -1;
    int *next = (int *)malloc(sizeof(int) * m);
    next[0] = 0;
    for (int i = 1, len = 0; i < m; ) {
        if (p[i] == p[len]) {
            next[i++] = ++len;
        } else if (len > 0) {
            len = next[len - 1];
        } else {
            next[i++] = 0;
        }
    }
    int i = 0, j = 0, ans = -1;
    while (i < n) {
        if (s[i] == p[j]) {
            i++; j++;
            if (j == m) { ans = i - m; break; }
        } else if (j > 0) {
            j = next[j - 1];
        } else {
            i++;
        }
    }
    free(next);
    return ans;
}

int removeRange(int a[], int n, int s, int t) {
    if (n <= 0 || s > t) return n;
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] < s || a[i] > t) {
            a[k++] = a[i];
        }
    }
    return k;
}

int enQueue(SqQueue *q, int x) {
    if (q->front == q->rear && q->tag == 1) {
        return 0;
    }
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXSIZE;
    q->tag = 1;
    return 1;
}

int pushShared(SharedStack *s, int stackNo, int x) {
    if (stackNo != 0 && stackNo != 1) return 0;
    if (s->top1 + 1 == s->top2) return 0;
    if (stackNo == 0) {
        s->data[++(s->top1)] = x;
    } else {
        s->data[--(s->top2)] = x;
    }
    return 1;
}

void dfsComp(int adj[][MAXV], int n, int u, int visited[]) {
    visited[u] = 1;
    for (int v = 0; v < n; v++) {
        if (adj[u][v] && !visited[v]) {
            dfsComp(adj, n, v, visited);
        }
    }
}
int countComponents(int adj[][MAXV], int n) {
    int visited[MAXV] = {0};
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            count++;
            dfsComp(adj, n, i, visited);
        }
    }
    return count;
}

void selectionSort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int minIdx = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[minIdx]) {
                minIdx = j;
            }
        }
        if (minIdx != i) {
            int tmp = a[i];
            a[i] = a[minIdx];
            a[minIdx] = tmp;
        }
    }
}

