int lowerBound(const int a[], int n, int target) {
    int low = 0, high = n;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (a[mid] >= target) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

int countSingleChild(BiNode *root) {
    if (root == NULL) return 0;
    int self = ((root->left != NULL && root->right == NULL) ||
                (root->left == NULL && root->right != NULL)) ? 1 : 0;
    return self + countSingleChild(root->left) + countSingleChild(root->right);
}

int partition(int a[], int low, int high) {
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot) high--;
        a[low] = a[high];
        while (low < high && a[low] <= pivot) low++;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}

int checkBST(BSTNode *node, long long minVal, long long maxVal) {
    if (node == NULL) return 1;
    if (node->key <= minVal || node->key >= maxVal) return 0;
    return checkBST(node->left, minVal, node->key) &&
           checkBST(node->right, node->key, maxVal);
}
int isValidBST(BSTNode *root) {
    return checkBST(root, -2147483649LL, 2147483648LL);
}
